import{_ as d,a8 as t,o as c,c as n,a as o,a3 as s,K as a,L as u,ah as h}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const v=JSON.parse('{"title":"媒体采编工具链开发踩坑（ASR / BrowserSkill / 路径 / URL分类）","description":"","frontmatter":{"type":"lesson","scope":"webnote","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["WebNote","ASR","faster-whisper","BrowserSkill","踩坑"]},"headers":[],"relativePath":"vault/Memory/Lessons/媒体采编工具链开发踩坑.md","filePath":"vault/Memory/Lessons/媒体采编工具链开发踩坑.md","lastUpdated":1789374053000}'),p={name:"vault/Memory/Lessons/媒体采编工具链开发踩坑.md"};function _(g,e,b,m,w,k){const l=t("VPNolebaseInlineLinkPreview"),r=t("NolebaseGitContributors"),i=t("NolebaseGitChangelog");return c(),n("div",null,[e[3]||(e[3]=o("h1",{id:"媒体采编工具链开发踩坑-asr-browserskill-路径-url分类",tabindex:"-1"},[s("媒体采编工具链开发踩坑（ASR / BrowserSkill / 路径 / URL分类） "),o("a",{class:"header-anchor",href:"#媒体采编工具链开发踩坑-asr-browserskill-路径-url分类","aria-label":"Permalink to “媒体采编工具链开发踩坑（ASR / BrowserSkill / 路径 / URL分类）”"},"​")],-1)),o("blockquote",null,[o("p",null,[e[1]||(e[1]=s("来源：2026-08-04/05 WebNote-Workflow 采编工具开发与测试会话。相关决策见 ",-1)),a(l,{href:"/knowledge/vault/Memory/Decisions/WebNote-Workflow架构决策-5Agent精简为主会话+3subagent.html"},{default:u(()=>[...e[0]||(e[0]=[s("WebNote-Workflow架构决策-5Agent精简为主会话+3subagent",-1)])]),_:1}),e[2]||(e[2]=s("。",-1))])]),e[4]||(e[4]=h('<h2 id="_1-faster-whisper-中文-asr" tabindex="-1">1. faster-whisper 中文 ASR <a class="header-anchor" href="#_1-faster-whisper-中文-asr" aria-label="Permalink to “1. faster-whisper 中文 ASR”">​</a></h2><ul><li><strong>繁体输出</strong>：<code>language=&#39;zh&#39;</code> 默认输出繁体。解法：<code>initial_prompt=&#39;以下是简体中文的语音转写：&#39;</code> 引导模型输出简体。</li><li><strong>large-v3 重复输出</strong>：同一段话反复出现（10 段全是同一句）。解法：<code>condition_on_previous_text=False</code>，避免模型用前文自我强化。</li><li><strong>VAD 分段异常</strong>：4 分钟音频只切出 10 个大段。解法：显式设置 <code>vad_parameters=dict(threshold=0.5, min_silence_duration_ms=500, speech_pad_ms=200)</code>。</li><li><strong>Systran/faster-whisper-large-v3-turbo 仓库已改私有</strong>（401 错误），用 <code>Systran/faster-whisper-large-v3</code> 替代，质量更好。</li><li><strong>16 核 CPU int8 实测速度</strong>：small 3.1x 实时（精度中，&quot;非全日制&quot;识别成&quot;飞拳指&quot;），large-v3 1.5x 实时（精度高）。默认用 large-v3。</li><li><strong>模型已在本地缓存</strong>：<code>C:/Users/stars/.cache/huggingface/hub/</code>（small 464MB + large-v3 3GB）。</li></ul><h2 id="_2-网络诊断-curl-不通-网络不通" tabindex="-1">2. 网络诊断：curl 不通 ≠ 网络不通 <a class="header-anchor" href="#_2-网络诊断-curl-不通-网络不通" aria-label="Permalink to “2. 网络诊断：curl 不通 ≠ 网络不通”">​</a></h2><p>Git Bash 的 curl 访问 huggingface.co / hf-mirror.com 全部返回 000（SSL 握手失败），但 Python urllib 完全正常（200）。<strong>诊断网络连通性必须用 Python <code>urllib.request</code> 测试</strong>，不要被 curl 的假阴性误导。<code>pip</code> 走清华镜像正常。</p><h2 id="_3-bsk-cli-browserskill-调用" tabindex="-1">3. bsk CLI（BrowserSkill）调用 <a class="header-anchor" href="#_3-bsk-cli-browserskill-调用" aria-label="Permalink to “3. bsk CLI（BrowserSkill）调用”">​</a></h2><ul><li><code>bsk evaluate</code> 的 JS 表达式是<strong>位置参数</strong>，不是 <code>--code</code>：<code>bsk evaluate --session &lt;id&gt; --json &#39;&lt;JS&gt;&#39;</code>。</li><li>JS 代码必须压成单行（多行含换行符作为 CLI 参数会出问题）。</li><li><code>--json</code> 输出格式是 <code>{&quot;ok&quot;: true, &quot;tab_id&quot;: N, &quot;value&quot;: &quot;...&quot;}</code>——<strong>结果在 <code>value</code> 字段，且 value 是 JSON 字符串需要二次 <code>json.loads</code></strong>。</li><li><code>bsk session stop &lt;SESSION_ID&gt;</code> 也是位置参数，不接受 <code>--session</code>。</li><li>完整流程：<code>session start</code> → <code>navigate</code> → <code>wait-ms 3000~5000</code> → <code>evaluate</code>（提取可见文本的 TreeWalker JS）→ <code>session stop</code>。</li></ul><h2 id="_4-windows-git-bash-路径混用" tabindex="-1">4. Windows + Git Bash 路径混用 <a class="header-anchor" href="#_4-windows-git-bash-路径混用" aria-label="Permalink to “4. Windows + Git Bash 路径混用”">​</a></h2><p><code>os.path.join(&#39;/e/temp/xxx&#39;, &#39;file.md&#39;)</code> 产生 <code>/e/temp/xxx\\file.md</code>（正反斜杠混用），<code>os.path.exists</code> 返回 False。解法：路径统一手拼 <code>/</code>（<code>TEST_DIR + &#39;/content&#39;</code>），或对用户输入做 <code>.replace(&#39;\\\\&#39;, &#39;/&#39;)</code>。MSYS 风格路径 <code>/e/...</code> Python 能识别目录本身，但 join 后的混合路径不行。</p><h2 id="_5-url-媒体格式分类优先级" tabindex="-1">5. URL 媒体格式分类优先级 <a class="header-anchor" href="#_5-url-媒体格式分类优先级" aria-label="Permalink to “5. URL 媒体格式分类优先级”">​</a></h2><ol><li><strong>文档扩展名最先判</strong>，且必须用 <code>urlparse(url).path</code> 取路径（<code>paper.pdf?download=1</code> 若直接 <code>endswith(&#39;.pdf&#39;)</code> 会漏判）。</li><li><strong>音频先于视频判</strong>：<code>music.youtube.com/watch</code> 会命中视频规则 <code>youtube.com/watch</code>，必须先匹配 <code>music.youtube.com</code>。</li><li>正文为空不能反推媒体格式（可能是付费墙或抓取失败），判不了就写&quot;无法判断&quot;。</li><li>降级路径模式（<code>/article/</code>、<code>/blog/</code>、<code>/posts/</code>）可兜底图文分类。</li></ol><h2 id="_6-测试方法沉淀" tabindex="-1">6. 测试方法沉淀 <a class="header-anchor" href="#_6-测试方法沉淀" aria-label="Permalink to “6. 测试方法沉淀”">​</a></h2><ul><li>30 用例分类测试（覆盖 5 媒体格式 + 边界：空URL/大小写/查询参数/文件不存在）先跑分类逻辑，再做端到端（真实 BrowserSkill 调 B站视频、pypdf 解析真实 PDF）。</li><li>端到端测试数据集要混格式（图文/视频/文档/无法判断各若干），虚构 URL（如编造的 YouTube 链接）的失败是预期行为，要与真实故障区分。</li></ul>',12)),a(r),a(i)])}const x=d(p,[["render",_]]);export{v as __pageData,x as default};
